#!/bin/sh
# Writes the Fortran module dependencies of the given sources as make rules:
#    a.o : b.o    when a.f90 uses a module defined in b.f90
# Used by the Makefile to generate .depend, so that a parallel build (make -j)
# compiles each module before the files that use it.
# Only modules defined in the given sources are kept (intrinsic and library
# modules are ignored). sha.f90 and operating_system.f90 are generated by the
# Makefile and may not exist yet: their modules (sha, os) are mapped directly.
# Fortran is case-insensitive: names are compared in lower case.

awk '
FNR == 1 {
   obj = FILENAME
   sub(/^.*\//, "", obj)          # gas/abo.f90 -> abo.f90 (objects are built in src/)
   sub(/\.[fF]90$/, ".o", obj)
}
{
   line = tolower($0)
   sub(/!.*/, "", line)           # comments
}
# module definition (not "module procedure" nor "module function/subroutine")
line ~ /^[ \t]*module[ \t]+[a-z0-9_]+[ \t]*$/ {
   name = line
   sub(/^[ \t]*module[ \t]+/, "", name)
   sub(/[ \t]*$/, "", name)
   if (name != "procedure") def[name] = obj
   next
}
# use statement: "use mod", "use mod, only : ...", "use :: mod", "use, intrinsic :: mod"
line ~ /^[ \t]*use[ \t,:]/ {
   if (line ~ /^[ \t]*use[ \t]*,[ \t]*intrinsic/) next
   name = line
   sub(/^[ \t]*use[ \t]*(::)?[ \t]*/, "", name)
   sub(/[ \t,].*$/, "", name)
   if (name != "") uses[obj, name] = 1
}
END {
   if (!("sha" in def)) def["sha"] = "sha.o"
   if (!("os" in def)) def["os"] = "operating_system.o"
   for (key in uses) {
      split(key, k, SUBSEP)
      if ((k[2] in def) && (def[k[2]] != k[1])) print k[1] " : " def[k[2]]
   }
}
' "$@" | sort -u
